public sealed class TestRoot
{
    public ActionRuntime Build()
    {
        var input     = new InputSystemAdapter();
        var pointer   = new PointerSystem(input);
        var objects   = new ObjectSystem();

        var handlers = new HandlerSet()
            .Add(new FindObjectHandler(objects))
            .Add(new ClickScreenHandler(pointer))
            .Add(new ClickObjectHandler());

        var hooks = new IActionHook[] { new LogHook(), new ScreenshotOnFailHook() };
        return new ActionRuntime(new ActionPipeline(handlers, hooks));
    }
}

public static class Actions
{
    public static Task<ExitCode> Run<T>(CommandContext cmd, IAction<T> action)
        => ActionRuntime.GetOrBuild().RunFromCli(cmd, action);
}

public sealed class ActionRuntime
{
    static ActionRuntime active;                       // the one singleton
    public static ActionRuntime GetOrBuild()
        => active ??= new TestRoot().Build();          // first call builds it

    readonly ActionPipeline pipeline;
    public ActionRuntime(ActionPipeline pipeline) => this.pipeline = pipeline;
    public Task<ExitCode> RunFromCli<T>(CommandContext cmd, IAction<T> action) { /* run, map result, exit code */ }
}

// 1. Command: CLI args to one action
[CliGroupCommand("ui", "Click an object by hierarchy path")]
internal static Task<ExitCode> ClickObject(CommandContext cmd,
    [CliArg("path", "Hierarchy path")] string path)
    => Actions.Run(cmd, new ClickObject(path));

// 2a. Simple action: route to a system
public sealed record ClickScreen(Vector2 Point) : IAction<Unit>;
sealed class ClickScreenHandler : IActionHandler<ClickScreen, Unit>
{
    readonly PointerSystem pointer;
    public ClickScreenHandler(PointerSystem pointer) => this.pointer = pointer;
    public Task<Unit> Handle(ClickScreen a, ActionContext ctx) => pointer.Click(a.Point, ctx.Cancel);
}

// 2b. Composite action: route and map, no logic
public sealed record ClickObject(string Path) : IAction<Unit>;
sealed class ClickObjectHandler : IActionHandler<ClickObject, Unit>
{
    public async Task<Unit> Handle(ClickObject a, ActionContext ctx)
    {
        var obj = await ctx.Run(new FindObject(a.Path));
        return await ctx.Run(new ClickScreen(obj.ScreenPoint));
    }
}

// 3. System: the logic. A plain class, no base.
public sealed class PointerSystem
{
    readonly IInputAdapter input;
    public PointerSystem(IInputAdapter input) => this.input = input;
    public async Task<Unit> Click(Vector2 p, CancellationToken ct) { /* down, wait 1 frame, up */ }
}

sealed class ScreenshotOnFailHook : IActionHook
{
    public Task Before(ActionContext ctx, IAction a) => Task.CompletedTask;
    public async Task After(ActionContext ctx, IAction a, ActionOutcome o)
    {
        if (o.Failed) await ctx.Evidence.Screenshot($"{ctx.StepId}_fail.png");
    }
}

public sealed class WalletSystem { public Task<long> Add(string currency, long amount, CancellationToken ct) { /* game code */ } }
public sealed record WalletAdd(string Currency, long Amount) : IAction<long>;
sealed class WalletAddHandler : IActionHandler<WalletAdd, long> { /* routes to WalletSystem */ }

[CliGroupCommand("wallet", "Add currency")]
internal static Task<ExitCode> Add(CommandContext cmd,
    [CliArg("currency", "Currency id")] string currency,
    [CliArg("amount", "Amount")] long amount)
    => Actions.Run(cmd, new WalletAdd(currency, amount));
